// ============================================================================
// OCP_apb: APB4 register wrapper around OCP_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/OCP.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/OCP.md
// ============================================================================
module OCP_apb #(
  parameter int DW = 32,
  parameter int AW = 32,
  parameter int DEPTH = 256,
  parameter int ACCEPT_DLY = 1
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic [2:0] mcmd,
  input logic [AW-1:0] maddr,
  input logic [DW-1:0] mdata,
  input logic [DW/8-1:0] mbyteen,
  input logic [1:0] mthreadid,
  output logic scmdaccept,
  output logic [DW-1:0] sdata,
  output logic [1:0] sresp,
  output logic [1:0] sthreadid
);
  localparam logic [31:0] ID_VALUE = 32'h4F430200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [4:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd5) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic          c_irq;
  OCP_top #(.DW(DW), .AW(AW), .DEPTH(DEPTH), .ACCEPT_DLY(ACCEPT_DLY)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .mcmd(mcmd),
    .maddr(maddr),
    .mdata(mdata),
    .mbyteen(mbyteen),
    .mthreadid(mthreadid),
    .scmdaccept(scmdaccept),
    .sdata(sdata),
    .sresp(sresp),
    .sthreadid(sthreadid),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
